95: * Screenshots: Gemma's vision reads them into "Name: message" lines. Desktop with Ollama only for
96: * now: the Gemma built into Ward reads text, not images (node-llama-cpp has no vision support yet).
98:export async function readScreenshots(files: File[]): Promise<string> {
100:  const images = await Promise.all(
112:  for (const img of images) {
125:              "This is a screenshot of a chat app. Write out every message, top to bottom, one per line, as `Name: message`. Use the sender name shown in the screenshot; for messages sent by the phone's owner (usually on the right), use `Me`. Copy the text exactly, in whatever language it is in. Output only the lines.",
126:            images: [img],
131:    if (!r.ok) throw new Error(`Couldn't read the screenshot (${r.status})`);

